# ============================================================
#  install.ps1 - установка личного VPN на Windows (PowerShell).
#  BUILD-2026-08-05a  (родной Windows-установщик, встроенный ssh, без WSL)
#  Режимы: (1) два сервера Россия+зарубеж  /  (2) только зарубеж.
#
#  Запуск ОДНОЙ строкой в обычном PowerShell:
#     irm https://2server-privacy.vercel.app/install.ps1 | iex
#
#  Серверные скрипты встроены ниже (base64). WSL/Git не нужны.
# ============================================================
$ErrorActionPreference = 'Stop'
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch {}
try { chcp 65001 > $null } catch {}

function Say($m){ Write-Host $m }

# ── проверка встроенного SSH-клиента Windows ──
if (-not (Get-Command ssh -ErrorAction SilentlyContinue)) {
  Say ""
  Say "На этом Windows не найден встроенный SSH-клиент (ssh)."
  Say "Включи его так: Параметры -> Приложения -> Дополнительные компоненты"
  Say "-> Добавить компонент -> 'Клиент OpenSSH' -> Установить."
  Say "Потом снова вставь команду установки VPN."
  return
}

$B64_VPN = ''
$B64_ENTRY = ''

$known = Join-Path $env:TEMP 'vpn_known_hosts.tmp'
$sshOpts = @('-o','StrictHostKeyChecking=no','-o',"UserKnownHostsFile=$known",'-o','ConnectTimeout=30','-o','ServerAliveInterval=30')

# ── запуск одного серверного скрипта по ssh (один ввод пароля на сервер) ──
function Invoke-ServerInstall($srvHost, $b64, $name, $envAssign) {
  $remoteCmd = "cat > /tmp/$name.b64 && base64 -di /tmp/$name.b64 > /tmp/$name.sh && $envAssign bash /tmp/$name.sh </dev/null; echo __VPNLINK__; cat /root/vpn-link.txt 2>/dev/null; echo __VPNLINKRU__; cat /root/vpn-link-ru.txt 2>/dev/null; echo __END__"
  Say ""
  Say ">>> Подключаюсь к $srvHost — введите root-пароль этого сервера, когда попросит."
  Say "    (символы пароля при вводе не отображаются — это нормально)"
  Say ""
  $b64 | ssh @sshOpts "root@$srvHost" $remoteCmd 2>&1 | Tee-Object -Variable capLines
  return ($capLines -join "`n")
}

function Get-Link($text, $startMark, $endMark) {
  $pat = [regex]::Escape($startMark) + '(.*?)' + [regex]::Escape($endMark)
  $m = [regex]::Match($text, $pat, [System.Text.RegularExpressions.RegexOptions]::Singleline)
  if ($m.Success) {
    $lm = [regex]::Match($m.Groups[1].Value, 'vless://\S+')
    if ($lm.Success) { return $lm.Value }
  }
  return ''
}

# ── выбор режима ──
Say "============================================================"
Say " Личный VPN — установка (Windows)"
Say "============================================================"
Say ""
Say "Что ставим?"
Say "  1 — ДВА сервера: Россия + зарубеж (на каждый день, обходит блокировки)"
Say "  2 — ТОЛЬКО зарубежный сервер (быстрее, но без обхода российских блокировок)"
Say ""
$MODE = ''
while ($MODE -ne '1' -and $MODE -ne '2') { $MODE = (Read-Host "Введите 1 или 2 и нажмите Enter").Trim() }

# ── данные серверов ──
Say ""
Say "-- Зарубежный сервер (ВЫХОД, напр. Нидерланды) --"
$HostExit   = (Read-Host "IP зарубежного сервера").Trim()
$DomainExit = (Read-Host "Домен выхода (de.вашдомен, A-запись уже на IP выхода)").Trim()
if ($MODE -eq '1') {
  Say ""
  Say "-- Российский сервер (ВХОД) --"
  $HostEntry   = (Read-Host "IP российского сервера").Trim()
  $DomainEntry = (Read-Host "Домен входа (ru.вашдомен, A-запись уже на IP входа)").Trim()
}
$Email = (Read-Host "Email для сертификатов Let's Encrypt").Trim()

# ── зарубежный выход (оба режима) ──
$capExit = Invoke-ServerInstall $HostExit $B64_VPN 'install_vpn' "DOMAIN=$DomainExit EMAIL=$Email"
$exitLink = Get-Link $capExit '__VPNLINK__' '__VPNLINKRU__'
if (-not $exitLink) {
  Say ""
  Say "!!! Не удалось получить ссылку с зарубежного сервера."
  Say "    Проверь IP/пароль/домен (A-запись de -> IP выхода) и запусти команду снова."
  return
}
$exitUuid = ([regex]::Match($exitLink, 'vless://([^@]+)@')).Groups[1].Value
$fastLink = ($exitLink -replace '#.*$', '') + '#VPN-Zarubezh-only'

# ── режим 2: только зарубеж ──
if ($MODE -eq '2') {
  Say ""
  Say "############################################################"
  Say "ГОТОВО. Зарубежный сервер поднят: $DomainExit -> интернет"
  Say ""
  Say ">>> ВАША ССЫЛКА (только зарубежный сервер) — вставьте в приложение Happ:"
  Say ""
  Say $fastLink
  Say "############################################################"
  return
}

# ── режим 1: российский вход (nginx-релей на выход) ──
$capEntry = Invoke-ServerInstall $HostEntry $B64_ENTRY 'install_entry' "DOMAIN=$DomainEntry EMAIL=$Email EXIT_DOMAIN=$DomainExit EXIT_UUID=$exitUuid"
$mainLink = Get-Link $capEntry '__VPNLINK__' '__VPNLINKRU__'
$ruLink   = Get-Link $capEntry '__VPNLINKRU__' '__END__'
if ($mainLink) { $mainLink = ($mainLink -replace '#.*$', '') + '#VPN-Rossiya-plus-Zarubezh' }
if ($ruLink)   { $ruLink   = ($ruLink   -replace '#.*$', '') + '#VPN-Rossiya-only' }

if (-not $mainLink) {
  Say ""
  Say "!!! Не удалось получить основную ссылку с российского сервера."
  Say "    Проверь IP/пароль/домен (A-запись ru -> IP входа) и запусти команду снова."
  return
}

Say ""
Say "############################################################"
Say "ГОТОВО. У вас ТРИ ссылки — добавьте нужные в Happ как профили:"
Say ""
Say "------------------------------------------------------------"
Say ">>> [1] ОСНОВНАЯ  —  Россия + зарубеж"
Say "    На каждый день. Обходит блокировки, работает и на РФ-сайтах,"
Say "    и на зарубежных. Вход: $DomainEntry (RU) -> выход $DomainExit."
Say ""
Say $mainLink
Say "------------------------------------------------------------"
Say ">>> [2] БЫСТРАЯ  —  только зарубеж"
Say "    Максимальная скорость. Зарубежный IP, для зарубежных сервисов."
Say ""
Say $fastLink
Say "------------------------------------------------------------"
if ($ruLink) {
  Say ">>> [3] РОССИЙСКАЯ  —  только Россия"
  Say "    Весь трафик через РФ-сервер, российский IP. Для доступа к"
  Say "    РФ-сервисам, например когда вы за границей."
  Say ""
  Say $ruLink
  Say "------------------------------------------------------------"
}
Say "############################################################"
